 p_id=>wwv_flow_imp.id(27167312714276454)
,p_name=>'Batch'
,p_static_id=>'batch-header'
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.batch_name,',
'       b.client_name,',
'       b.target_env,',
'       to_char(b.cutover_date, ''YYYY-MM-DD'') cutover_date,',
'       s.status_name,',
'       b.readiness_score,',
'       nvl(b.readiness_status, ''NOT_VALIDATED'') readiness_status,',
'       case b.readiness_status',
'           when ''NOT_READY''           then ''fv-st-danger''',
'           when ''READY_WITH_WARNINGS'' then ''fv-st-warning''',
'           when ''READY''               then ''fv-st-success''',
'           else ''fv-st-neutral''',
'       end readiness_css,',
'       b.line_count,',
'       b.error_count,',
'       b.warning_count,',
'       b.info_count,',
'       to_char(b.last_validated_on, ''YYYY-MM-DD HH24:MI'') last_validated_on',
'  from xxx_fv_batches b',
'  join xxx_fv_batch_statuses s',
'    on s.status_code = b.status_code',
' where b.batch_id = :FV_BATCH_ID'))
,p_display_when_condition=>':APP_PAGE_ID in (''10'', ''20'', ''30'', ''40'')'
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
